mapper.select:
SELECT TA.* FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.FRST_REGIST_PNTTM DESC) AS RNUM, A.SCH_CODE AS "schCode", A.SCH_NAME AS "schName", FN_DAYCONVERT(A.SCH_STARTDAY) AS "schStartDay", FN_DAYCONVERT(A.SCH_ENDDAY) AS "schEndDay", A.GROUP_CODE AS "groupCode", B.GROUP_NM AS "groupNm", A.CONTENT_CODE AS "contentCode", fn_contentNm(A.CONTENT_CODE) AS "conNm", A.SCH_EMERGUBUN AS "schEmerGubun", A.SCH_USEYN AS "schUseYn" FROM TB_SCHEDULE A JOIN TB_GROUP B ON A.GROUP_CODE = B.GROUP_CODE WHERE 1=1
AND A.GROUP_ID IN ( WITH RECURSIVE cte AS ( SELECT GROUP_ID, PARENT_GROUP_ID FROM LETTNAUTHORGROUPINFO WHERE GROUP_ID = #{groupId} UNION ALL SELECT g.GROUP_ID, g.PARENT_GROUP_ID FROM LETTNAUTHORGROUPINFO g JOIN cte ON g.PARENT_GROUP_ID = cte.GROUP_ID ) SELECT GROUP_ID FROM cte )
AND A.CENTER_ID = #{centerId}
AND A.SCH_NAME LIKE CONCAT('%', #{searchKeyword}, '%')
AND A.SCH_CODE LIKE CONCAT('%', #{searchKeyword}, '%')
) TA WHERE TA.RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}
